    #[test]
    fn psubb_register_decodes_all_xmm_pairs_and_rejects_out_of_slice_encodings() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let code = if destination >= 8 || source >= 8 {
                    vec![0x66, rex, 0x0f, 0xf8, modrm]
                } else {
                    vec![0x66, 0x0f, 0xf8, modrm]
                };
                let mut memory = Memory::new(&code);
                let decoded = memory.decode().unwrap_or_else(|error| {
                    panic!("dest={destination} src={source} rex={rex:02x}: {error:?}")
                });
                assert_eq!(
                    decoded.operation,
                    Operation::PsubbRegister {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, code.len() as u8);
            }
        }
        for bytes in [
            &[0x0f, 0xf8, 0xc1][..], // MMX form is not admitted.
            &[0x66, 0xf2, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0xf3, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0x67, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0xf0, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0x48, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0x42, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0x40, 0x41, 0x0f, 0xf8, 0xc1][..],
            &[0x66, 0x0f, 0xf8, 0x01][..], // memory form
            &[0x66, 0x0f, 0xf8][..],
            &[0x66, 0x0f][..],
            &[0xc5, 0xf9, 0xf8, 0xc1][..],
            &[0xc4, 0xe1, 0x79, 0xf8, 0xc1][..],
            &[0x62, 0xf1, 0x7d, 0x08, 0xf8, 0xc1][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
    }

    #[test]
    fn pshufd_register_decodes_all_xmm_pairs_and_rejects_out_of_slice_encodings() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut code = vec![0x66];
                if destination >= 8 || source >= 8 {
                    code.push(rex);
                }
                code.extend([0x0f, 0x70, modrm, 0xe4]);
                let mut memory = Memory::new(&code);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::PshufdRegister {
                        destination,
                        source,
                        control: 0xe4
                    }
                );
                assert_eq!(decoded.length, code.len() as u8);
            }
        }
        for bytes in [
            &[0x0f, 0x70, 0xc1, 0xe4][..], // MMX form is not admitted.
            &[0x66, 0xf2, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0xf3, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0x67, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0xf0, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0x48, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0x42, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0x40, 0x41, 0x0f, 0x70, 0xc1, 0xe4][..],
            &[0x66, 0x0f, 0x70, 0x01, 0xe4][..], // memory form
            &[0x66, 0x0f, 0x70, 0xc1][..],       // missing imm8
            &[0xc5, 0xf9, 0x70, 0xc1, 0xe4][..],
            &[0xc4, 0xe1, 0x79, 0x70, 0xc1, 0xe4][..],
            &[0x62, 0xf1, 0x7d, 0x08, 0x70, 0xc1, 0xe4][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
        for code in [
            &[0x66, 0x0f, 0x70, 0xc1][..],
            &[0x66, 0x45, 0x0f, 0x70, 0xc1][..],
        ] {
            let mut memory = Memory::new(code);
            assert!(matches!(memory.decode(), Err(DecodeError::Memory(_))));
            assert_eq!(memory.fetched.len(), code.len() + 1);
        }
    }

    #[test]
    fn psllw_immediate_register_decodes_rmb_destination_and_strict_encoding() {
        for destination in 0..16u8 {
            let mut code = vec![0x66];
            if destination >= 8 {
                code.push(0x41);
            }
            code.extend([0x0f, 0x71, 0xf0 | (destination & 7), 0xff]);
            let mut memory = Memory::new(&code);
            let decoded = memory.decode().unwrap();
            assert_eq!(
                decoded.operation,
                Operation::PsllwImmediateRegister {
                    destination,
                    count: 0xff
                }
            );
            assert_eq!(decoded.length, code.len() as u8);
        }
        let mut psrlw = Memory::new(&[0x66, 0x0f, 0x71, 0xd1, 1]);
        assert_eq!(
            psrlw.decode().unwrap().operation,
            Operation::PsrlwImmediateRegister {
                destination: 1,
                count: 1,
            }
        );
        for bytes in [
            &[0x0f, 0x71, 0xf1, 1][..],
            &[0x66, 0x0f, 0x71, 0xd9, 1][..],
            &[0x66, 0x40, 0x0f, 0x71, 0xf1, 1][..],
            &[0x66, 0x0f, 0x71, 0x71, 1][..],
            &[0x66, 0x0f, 0x71, 0xf1][..],
            &[0x66, 0x48, 0x0f, 0x71, 0xf1, 1][..],
            &[0x66, 0x42, 0x0f, 0x71, 0xf1, 1][..],
            &[0x66, 0x45, 0x0f, 0x71, 0xf1, 1][..],
            &[0xc5, 0xf9, 0x71, 0xf1, 1][..],
        ] {
            assert!(Memory::new(bytes).decode().is_err(), "{bytes:02x?}");
        }
    }

