    #[test]
    fn orpd_register_decodes_exact_mandatory_66_high_register_forms() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut memory = Memory::new(&[0x66, rex, 0x0f, 0x56, modrm]);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::OrpdRegister {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, 5);
                if destination < 8 && source < 8 {
                    let mut bare_rex = Memory::new(&[0x66, 0x0f, 0x56, modrm]);
                    assert_eq!(
                        bare_rex.decode().unwrap().operation,
                        Operation::OrpdRegister {
                            destination,
                            source
                        }
                    );
                }
            }
        }
        for bytes in [
            &[0xf2, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0xf3, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0x67, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0xf0, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0x2e, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0x66, 0x66, 0x0f, 0x56, 0xc1][..],
            &[0x0f, 0x66, 0x56, 0xc1][..],
            &[0x66, 0x48, 0x0f, 0x56, 0xc1][..],
            &[0x66, 0x42, 0x0f, 0x56, 0xc1][..],
            &[0x66, 0x40, 0x41, 0x0f, 0x56, 0xc1][..],
            &[0x66, 0x0f, 0x56, 0x01][..],
            &[0x66, 0x0f, 0x56][..],
            &[0x66, 0x0f][..],
            &[0xc5, 0xf9, 0x56, 0xc1][..],
            &[0x62, 0xf1, 0x7d, 0x08, 0x56, 0xc1][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
        for (bytes, expected) in [
            (
                &[0x0f, 0x56, 0xc1][..],
                Operation::OrpsRegister {
                    destination: 0,
                    source: 1,
                },
            ),
            (
                &[0x66, 0x0f, 0x54, 0xc1][..],
                Operation::AndpdRegister {
                    destination: 0,
                    source: 1,
                },
            ),
            (
                &[0x66, 0x0f, 0x57, 0xc1][..],
                Operation::XorpdRegister {
                    destination: 0,
                    source: 1,
                },
            ),
            (
                &[0x66, 0x0f, 0x55, 0xc1][..],
                Operation::AndnpdRegister {
                    destination: 0,
                    source: 1,
                },
            ),
            (
                &[0x66, 0x0f, 0xeb, 0xc1][..],
                Operation::PorRegister {
                    destination: 0,
                    source: 1,
                },
            ),
        ] {
            let decoded = Memory::new(bytes).decode().unwrap();
            assert_eq!(decoded.operation, expected, "{bytes:02x?}");
        }
    }

    #[test]
    fn andnpd_register_decodes_exact_mandatory_66_high_register_forms() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut bytes = vec![0x66];
                if rex != 0x40 {
                    bytes.push(rex);
                }
                bytes.extend([0x0f, 0x55, modrm]);
                let mut memory = Memory::new(&bytes);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::AndnpdRegister {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, bytes.len() as u8);
            }
        }
        for bytes in [
            &[0x66, 0x0f, 0x55, 0x01][..],
            &[0x66, 0x48, 0x0f, 0x55, 0xc1],
            &[0x66, 0x42, 0x0f, 0x55, 0xc1],
            &[0x66, 0x66, 0x0f, 0x55, 0xc1],
            &[0xf2, 0x66, 0x0f, 0x55, 0xc1],
            &[0x66, 0x67, 0x0f, 0x55, 0xc1],
            &[0x66, 0x0f, 0x55],
            &[0x66, 0x0f],
            &[0xc5, 0xf9, 0x55, 0xc1],
            &[0x62, 0xf1, 0x7d, 0x08, 0x55, 0xc1],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
        let mut andnps = Memory::new(&[0x0f, 0x55, 0xc1]);
        assert!(matches!(
            andnps.decode().unwrap().operation,
            Operation::AndnpsRegister { .. }
        ));
        for bytes in [
            &[0x66, 0x0f, 0x54, 0xc1][..], // ANDPD
            &[0x66, 0x0f, 0x56, 0xc1][..], // ORPD
            &[0x66, 0x0f, 0x57, 0xc1][..], // XORPD
            &[0x66, 0x0f, 0xdb, 0xc1][..], // PAND
            &[0x66, 0x0f, 0xdf, 0xc1][..], // PANDN
        ] {
            let mut memory = Memory::new(bytes);
            assert!(!matches!(
                memory.decode().unwrap().operation,
                Operation::AndnpdRegister { .. }
            ));
        }
        assert_eq!(
            Memory::new(&[0x66, 0x0f, 0xdf, 0xc1])
                .decode()
                .unwrap()
                .operation,
            Operation::PandnRegister {
                destination: 0,
                source: 1
            }
        );
    }

