    #[test]
    fn rcpss_register_decodes_all_xmm_pairs_and_rejects_other_encodings() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let code = [0xf3, rex, 0x0f, 0x53, modrm];
                let mut memory = Memory::new(&code);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::RcpssRegister {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, 5);
                if rex == 0x40 {
                    let mut bare_rex = Memory::new(&[0xf3, 0x40, 0x0f, 0x53, modrm]);
                    assert_eq!(bare_rex.decode().unwrap().operation, decoded.operation);
                }
                if destination < 8 && source < 8 {
                    let mut bare = Memory::new(&[0xf3, 0x0f, 0x53, modrm]);
                    assert_eq!(bare.decode().unwrap().operation, decoded.operation);
                }
            }
        }

        let mut rsqrtss = Memory::new(&[0xf3, 0x0f, 0x52, 0xc1]);
        assert_eq!(
            rsqrtss.decode().unwrap().operation,
            Operation::RsqrtssRegister {
                destination: 0,
                source: 1
            }
        );

        for bytes in [
            &[0xf3, 0x0f, 0x53, 0x01][..],             // memory operand
            &[0xf3, 0x48, 0x0f, 0x53, 0xc1][..],       // REX.W
            &[0xf3, 0x42, 0x0f, 0x53, 0xc1][..],       // REX.X
            &[0xf3, 0x40, 0x41, 0x0f, 0x53, 0xc1][..], // multiple REX
            &[0x40, 0xf3, 0x0f, 0x53, 0xc1][..],       // nonadjacent REX
            &[0xf3, 0x66, 0x0f, 0x53, 0xc1][..],       // operand-size prefix
            &[0x66, 0xf3, 0x0f, 0x53, 0xc1][..],       // wrong prefix order
            &[0xf2, 0x0f, 0x53, 0xc1][..],
            &[0x2e, 0xf3, 0x0f, 0x53, 0xc1][..], // segment override
            &[0x67, 0xf3, 0x0f, 0x53, 0xc1][..], // address-size override
            &[0xf0, 0xf3, 0x0f, 0x53, 0xc1][..], // lock prefix
            &[0xf3, 0x0f, 0x53][..],
            &[0xf3, 0x45, 0x0f, 0x53][..], // truncated ModR/M
            &[0xf3, 0x0f][..],
            &[0xf3][..],
            &[0xc5, 0xf8, 0x53, 0xc1][..],             // VEX
            &[0xc4, 0xe1, 0x7a, 0x53, 0xc1][..],       // VEX
            &[0x62, 0xf1, 0x7e, 0x08, 0x53, 0xc1][..], // EVEX
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
    }

    #[test]
    fn rsqrtps_register_decodes_all_xmm_pairs_and_rejects_other_encodings() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut memory = Memory::new(&[rex, 0x0f, 0x52, modrm]);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::RsqrtpsRegister {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, 4);
                if rex == 0x40 {
                    let mut bare_rex = Memory::new(&[0x40, 0x0f, 0x52, modrm]);
                    assert_eq!(bare_rex.decode().unwrap().operation, decoded.operation);
                }
                if destination < 8 && source < 8 {
                    let mut bare = Memory::new(&[0x0f, 0x52, modrm]);
                    let bare_decoded = bare.decode().unwrap();
                    assert_eq!(bare_decoded.operation, decoded.operation);
                    assert_eq!(bare_decoded.length, 3);
                }
            }
        }

        for bytes in [
            &[0x0f, 0x52, 0x01][..],             // memory operand
            &[0x48, 0x0f, 0x52, 0xc1][..],       // REX.W
            &[0x42, 0x0f, 0x52, 0xc1][..],       // REX.X
            &[0x40, 0x41, 0x0f, 0x52, 0xc1][..], // multiple REX
            &[0x40, 0x66, 0x0f, 0x52, 0xc1][..], // nonadjacent REX
            &[0x66, 0x0f, 0x52, 0xc1][..],       // operand-size prefix
            &[0xf2, 0x0f, 0x52, 0xc1][..],       // wrong mandatory prefix
            &[0x2e, 0x0f, 0x52, 0xc1][..],       // segment override
            &[0x67, 0x0f, 0x52, 0xc1][..],       // address-size override
            &[0xf0, 0x0f, 0x52, 0xc1][..],       // LOCK prefix
            &[0x0f, 0x52][..],
            &[0x40, 0x0f, 0x52][..],                   // truncated ModR/M
            &[0xc5, 0xf8, 0x52, 0xc1][..],             // VEX
            &[0xc4, 0xe1, 0x78, 0x52, 0xc1][..],       // VEX
            &[0x62, 0xf1, 0x7c, 0x08, 0x52, 0xc1][..], // EVEX
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
        let mut sqrtps = Memory::new(&[0x0f, 0x51, 0xc1]);
        assert_eq!(
            sqrtps.decode().unwrap().operation,
            Operation::SqrtpsRegister {
                destination: 0,
                source: 1
            }
        );
    }

