    fn minsd_register_masked_decodes_all_xmm_pairs_and_rejects_other_encodings() {
        for destination in 0..16u8 {
            for source in 0..16u8 {
                let rex = 0x40 | ((destination >> 3) << 2) | (source >> 3);
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let bytes = if rex == 0x40 {
                    vec![0xf2, 0x0f, 0x5d, modrm]
                } else {
                    vec![0xf2, rex, 0x0f, 0x5d, modrm]
                };
                let mut memory = Memory::new(&bytes);
                let decoded = memory.decode().unwrap();
                assert_eq!(
                    decoded.operation,
                    Operation::MinsdRegisterMasked {
                        destination,
                        source
                    }
                );
                assert_eq!(decoded.length, bytes.len() as u8);
                if destination < 8 && source < 8 {
                    let mut bare_rex = Memory::new(&[0xf2, 0x40, 0x0f, 0x5d, modrm]);
                    assert_eq!(bare_rex.decode().unwrap().operation, decoded.operation);
                    let mut scalar_minss = Memory::new(&[0xf3, 0x0f, 0x5d, modrm]);
                    assert!(matches!(
                        scalar_minss.decode().unwrap().operation,
                        Operation::MinssRegisterMasked { .. }
                    ));
                }
            }
        }

        for bytes in [
            &[0xf2, 0x0f, 0x5d, 0x01][..],             // memory operand
            &[0xf2, 0x48, 0x0f, 0x5d, 0xc1][..],       // REX.W
            &[0xf2, 0x42, 0x0f, 0x5d, 0xc1][..],       // REX.X
            &[0xf2, 0x40, 0x41, 0x0f, 0x5d, 0xc1][..], // repeated REX
            &[0x40, 0xf2, 0x0f, 0x5d, 0xc1][..],       // nonadjacent REX
            &[0xf2, 0xf2, 0x0f, 0x5d, 0xc1][..],       // repeated mandatory prefix
            &[0xf2, 0x66, 0x0f, 0x5d, 0xc1][..],       // operand-size prefix
            &[0x66, 0xf2, 0x0f, 0x5d, 0xc1][..],       // wrong prefix order
            &[0x2e, 0xf2, 0x0f, 0x5d, 0xc1][..],       // segment override
            &[0x67, 0xf2, 0x0f, 0x5d, 0xc1][..],       // address-size override
            &[0xf0, 0xf2, 0x0f, 0x5d, 0xc1][..],       // LOCK prefix
            &[0xf2, 0x0f, 0x5d][..],                   // truncated ModR/M
            &[0xf2, 0x45, 0x0f, 0x5d][..],             // truncated REX form
            &[0xc5, 0xfb, 0x5d, 0xc1][..],             // VEX
            &[0xc4, 0xe1, 0x7b, 0x5d, 0xc1][..],       // VEX
            &[0x62, 0xf1, 0xff, 0x08, 0x5d, 0xc1][..], // EVEX
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err(), "{bytes:02x?}");
        }
    }

    #[test]
    fn minsd_memory_rax_decodes_only_exact_f2_0f_5d_00() {
        let mut exact = Memory::new(&[0xf2, 0x0f, 0x5d, 0x00]);
        let decoded = exact.decode().unwrap();
        assert_eq!(decoded.operation, Operation::MinsdMemoryRax);
        assert_eq!(decoded.length, 4);

        for (modrm, destination, source) in [(0xc0, 0, 0), (0xc1, 0, 1), (0xff, 7, 7)] {
            let mut register = Memory::new(&[0xf2, 0x0f, 0x5d, modrm]);
            let decoded = register.decode().unwrap();
            assert_eq!(
                decoded.operation,
                Operation::MinsdRegisterMasked {
                    destination,
                    source,
                }
            );
            assert_eq!(decoded.length, 4);
        }

        for bytes in [
            &[0xf2, 0x0f, 0x5d, 0xc0][..],             // register source
            &[0xf2, 0x48, 0x0f, 0x5d, 0x00][..],       // REX.W
            &[0xf2, 0x41, 0x0f, 0x5d, 0x00][..],       // REX.B selects R8
            &[0xf2, 0x44, 0x0f, 0x5d, 0x00][..],       // REX.R changes destination
            &[0x0f, 0x5d, 0x00][..],                   // MINPS prefix neighbor
            &[0xf3, 0x0f, 0x5d, 0x00][..],             // MINSS prefix neighbor
            &[0x66, 0x0f, 0x5d, 0x00][..],             // MINPD prefix neighbor
            &[0x66, 0xf2, 0x0f, 0x5d, 0x00][..],       // reversed prefixes
            &[0xf2, 0x0f, 0x5d][..],                   // truncated ModR/M
            &[0xc5, 0xfb, 0x5d, 0x00][..],             // VEX
            &[0x62, 0xf1, 0xff, 0x08, 0x5d, 0x00][..], // EVEX
        ] {
            let mut memory = Memory::new(bytes);
            assert!(
                !memory
                    .decode()
                    .is_ok_and(|decoded| decoded.operation == Operation::MinsdMemoryRax),
                "{bytes:02x?}"
            );
        }
    }

