    #[test]
    fn da_e9_fucompp_and_da_c1_fcmovb_are_exact_bare_encodings() {
        let mut memory = Memory::new(&[0xda, 0xe9]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.operation, Operation::Fucompp);
        assert_eq!(instruction.length, 2);
        assert_eq!(instruction.prefixes, Prefixes::default());
        assert_eq!(memory.fetched, [0xfff, 0x1000]);

        for source in 0..8u8 {
            let fcmovb = Memory::new(&[0xda, 0xc0 | source]).decode().unwrap();
            assert_eq!(fcmovb.operation, Operation::Fcmovb { source });
            assert_eq!(fcmovb.length, 2);
            assert_eq!(fcmovb.prefixes, Prefixes::default());
            let fcmovbe = Memory::new(&[0xda, 0xd0 | source]).decode().unwrap();
            assert_eq!(fcmovbe.operation, Operation::Fcmovbe { source });
            assert_eq!(fcmovbe.length, 2);
            assert_eq!(fcmovbe.prefixes, Prefixes::default());
        }

        for modrm in 0u8..=u8::MAX {
            let decoded = Memory::new(&[0xda, modrm]).decode();
            assert_eq!(
                decoded.map(|instruction| instruction.operation),
                match modrm {
                    0xe9 => Ok(Operation::Fucompp),
                    0xc0..=0xc7 => Ok(Operation::Fcmovb { source: modrm & 7 }),
                    0xc8..=0xcf => Ok(Operation::Fcmove { source: modrm & 7 }),
                    0xd0..=0xd7 => Ok(Operation::Fcmovbe { source: modrm & 7 }),
                    0xd8..=0xdf => Ok(Operation::Fcmovu { source: modrm & 7 }),
                    _ => Err(DecodeError::Unsupported {
                        opcode: Opcode {
                            map: OpcodeMap::Primary,
                            byte: 0xda,
                        },
                        length: 2,
                    }),
                },
                "DA {modrm:02x}"
            );
        }
        for prefix in [
            0xf0, 0xf2, 0xf3, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65, 0x66, 0x67, 0x9b,
        ]
        .into_iter()
        .chain(0x40..=0x4f)
        {
            assert!(matches!(
                Memory::new(&[prefix, 0xda, 0xe9]).decode(),
                Err(DecodeError::Unsupported { .. })
            ));
            assert!(matches!(
                Memory::new(&[prefix, 0xda, 0xc7]).decode(),
                Err(DecodeError::Unsupported { .. })
            ));
            assert!(matches!(
                Memory::new(&[prefix, 0xda, 0xd1]).decode(),
                Err(DecodeError::Unsupported { .. })
            ));
        }
        assert!(matches!(
            Memory::new(&[0xda]).decode(),
            Err(DecodeError::Memory(MemoryError::Unmapped {
                access: AccessKind::Fetch,
                ..
            }))
        ));
        assert!(matches!(
            Memory::new(&[0x9b, 0xda, 0xe9]).decode(),
            Err(DecodeError::Unsupported { .. })
        ));
        for prefix in [0x66, 0x48, 0x9b] {
            assert!(Memory::new(&[prefix, 0xda, 0xc9]).decode().is_err());
            assert!(Memory::new(&[prefix, 0xda, 0xd1]).decode().is_err());
        }
    }

    #[test]
    fn exact_bare_db_c0_c7_fcmovnb_preserves_db_neighbors_and_rejects_prefixes() {
        for modrm in 0u8..=u8::MAX {
            let decoded = Memory::new(&[0xdb, modrm]).decode();
            if (0xc0..=0xc7).contains(&modrm) {
                assert_eq!(
                    decoded.unwrap().operation,
                    Operation::Fcmovnb { source: modrm & 7 }
                );
            } else if matches!(
                modrm,
                0xc8..=0xcf | 0xd0..=0xdf | 0xe2 | 0xe3 | 0xe8..=0xef | 0xf0..=0xf7 | 0x00 | 0x10 | 0x18 | 0x28 | 0x38
            ) {
                assert!(decoded.is_ok(), "existing DB {modrm:02x} changed");
            } else {
                assert!(decoded.is_err(), "unexpected DB {modrm:02x}");
            }
        }
        for modrm in 0xc0..=0xc7 {
            for prefix in [0x66, 0x48, 0x9b] {
                assert!(Memory::new(&[prefix, 0xdb, modrm]).decode().is_err());
            }
        }
    }

