    #[test]
    fn qword_register_xadd_decodes_only_the_bare_profile_form() {
        let mut memory = Memory::new(&[0x48, 0x0f, 0xc1, 0xc0]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 4);
        assert_eq!(
            instruction.operation,
            Operation::Xadd {
                destination: RegisterView::low(Register::Rax, OperandSize::Qword),
                source: RegisterView::low(Register::Rax, OperandSize::Qword),
            }
        );
        assert_eq!(instruction.flag_effects().defined, crate::ARITHMETIC_FLAGS);

        let mut memory_form = Memory::new(&[0x48, 0x0f, 0xb1, 0x18]);
        let memory_instruction = memory_form.decode().unwrap();
        assert_eq!(memory_instruction.length, 4);
        assert_eq!(
            memory_instruction.operation,
            Operation::CmpxchgMemory {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
                source: RegisterView::low(Register::Rbx, OperandSize::Qword),
            }
        );
        assert_eq!(
            memory_instruction.flag_effects().defined,
            crate::ARITHMETIC_FLAGS
        );

        let mut extended = Memory::new(&[0x4d, 0x0f, 0xc1, 0xc8]);
        assert_eq!(
            extended.decode().unwrap().operation,
            Operation::Xadd {
                destination: RegisterView::low(Register::R8, OperandSize::Qword),
                source: RegisterView::low(Register::R9, OperandSize::Qword),
            }
        );

        let mut memory_form = Memory::new(&[0x48, 0x0f, 0xc1, 0x00]);
        assert_eq!(
            memory_form.decode().unwrap().operation,
            Operation::XaddMemory {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
                source: RegisterView::low(Register::Rax, OperandSize::Qword),
            }
        );

        for bytes in [
            &[0x0f, 0xc1, 0xc0][..], // default dword width
            &[0x66, 0x48, 0x0f, 0xc1, 0xc0],
            &[0x67, 0x48, 0x0f, 0xc1, 0xc0],
            &[0x2e, 0x48, 0x0f, 0xc1, 0xc0],
            &[0xf0, 0x48, 0x0f, 0xc1, 0xc0],
            // S4-38L9k: the default dword memory destination (`0f c1 00`) decodes now (see
            // `plain_memory_xadd_and_cmpxchg_decode_as_the_bare_memory_operations`).
            &[0x66, 0x48, 0x0f, 0xc1, 0x00],
            &[0x67, 0x48, 0x0f, 0xc1, 0x00],
            &[0x2e, 0x48, 0x0f, 0xc1, 0x00],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn lock_memory_xadd_decodes_the_qword_and_dword_forms_only() {
        // S4-38L7ay: the LOCK memory form is `LockXaddMem` (S2-21f decoded it as `XaddMemory`,
        // which is now the bare form only); the dword form (no REX.W) is new.
        let mut memory = Memory::new(&[0xf0, 0x49, 0x0f, 0xc1, 0x0c, 0x24]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 6);
        assert_eq!(instruction.prefixes.group1, Some(0xf0));
        assert_eq!(
            instruction.operation,
            Operation::LockXaddMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::R12),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
                source: RegisterView::low(Register::Rcx, OperandSize::Qword),
            }
        );

        let mut memory = Memory::new(&[0xf0, 0x44, 0x0f, 0xc1, 0x00]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 5);
        assert_eq!(
            instruction.operation,
            Operation::LockXaddMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Dword,
                },
                source: RegisterView::low(Register::R8, OperandSize::Dword),
            }
        );
        let mut memory = Memory::new(&[0xf0, 0x0f, 0xc1, 0x00]);
        assert!(matches!(
            memory.decode().unwrap().operation,
            Operation::LockXaddMem { destination, .. } if destination.size == OperandSize::Dword
        ));

        for bytes in [
            &[0xf0, 0x48, 0x0f, 0xc1, 0xc0][..], // LOCK register destination
            &[0xf0, 0x0f, 0xc1, 0xc0][..],       // LOCK dword register destination
            // S4-38L9k: the bare dword memory destination (`0f c1 00`) decodes as `XaddMemory`.
            &[0xf0, 0x66, 0x48, 0x0f, 0xc1, 0x00],
            &[0xf0, 0x66, 0x0f, 0xc1, 0x00],
            &[0xf0, 0x67, 0x48, 0x0f, 0xc1, 0x00],
            &[0xf0, 0x67, 0x0f, 0xc1, 0x00],
            &[0xf0, 0x2e, 0x48, 0x0f, 0xc1, 0x00],
            &[0xf0, 0x2e, 0x0f, 0xc1, 0x00],
            &[0xf2, 0x48, 0x0f, 0xc1, 0x00],
            &[0xf3, 0x48, 0x0f, 0xc1, 0x00],
            &[0xf0, 0xf0, 0x48, 0x0f, 0xc1, 0x00],
            &[0x48, 0xf0, 0x0f, 0xc1, 0x00], // REX before LOCK
            &[0x41, 0xf0, 0x0f, 0xc1, 0x00],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn ds_memory_xadd_decodes_the_qword_and_dword_forms_only() {
        // S4-38L9g: `3E [REX] 0F C1 /r` with a memory destination is `XaddDsMem`.
        let mut memory = Memory::new(&[0x3e, 0x48, 0x0f, 0xc1, 0x87, 0x48, 0x05, 0x00, 0x00]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 9);
        assert_eq!(instruction.prefixes.segment, Some(0x3e));
        assert_eq!(
            instruction.operation,
            Operation::XaddDsMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rdi),
                    index: None,
                    scale: 1,
                    displacement: 0x548,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
                source: RegisterView::low(Register::Rax, OperandSize::Qword),
            }
        );
        assert_eq!(instruction.flag_effects().defined, crate::ARITHMETIC_FLAGS);

        let mut memory = Memory::new(&[0x3e, 0x44, 0x0f, 0xc1, 0x00]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 5);
        assert_eq!(
            instruction.operation,
            Operation::XaddDsMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Dword,
                },
                source: RegisterView::low(Register::R8, OperandSize::Dword),
            }
        );

        for bytes in [
            &[0x3e, 0x0f, 0xc1, 0xc0][..], // register destination
            &[0x3e, 0x48, 0x0f, 0xc1, 0xc0][..],
            &[0x3e, 0xf0, 0x48, 0x0f, 0xc1, 0x00], // LOCK + DS, either order
            &[0xf0, 0x3e, 0x0f, 0xc1, 0x00],
            &[0x3e, 0x66, 0x0f, 0xc1, 0x00],
            &[0x3e, 0x67, 0x48, 0x0f, 0xc1, 0x00],
            &[0x3e, 0xf3, 0x0f, 0xc1, 0x00],
            &[0x2e, 0x0f, 0xc1, 0x00], // CS/ES/SS/FS/GS
            &[0x26, 0x48, 0x0f, 0xc1, 0x00],
            &[0x36, 0x0f, 0xc1, 0x00],
            &[0x64, 0x48, 0x0f, 0xc1, 0x00],
            // S4-38L9x: `65 0f c1 00` (GS dword) became decoding (`XaddGsMem`); the qword is refused.
            &[0x3e, 0x3e, 0x48, 0x0f, 0xc1, 0x00], // repeated or mixed overrides
            &[0x2e, 0x3e, 0x0f, 0xc1, 0x00],
            &[0x3e, 0x64, 0x0f, 0xc1, 0x00],
            &[0x48, 0x3e, 0x0f, 0xc1, 0x00], // REX before DS
            &[0x3e, 0x48, 0x40, 0x0f, 0xc1, 0x00],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn segment_memory_xadd_decodes_the_byte_word_and_dword_forms_for_fs_and_gs() {
        // S4-38L9x: `[64|65] [66] [REX] 0F C0|C1 /r` with a memory destination. The S4-38L9w
        // boundary `65 0f c1 02` is `xaddl %eax, %gs:(%rdx)`.
        let rdx = |size| MemoryOperand {
            base: AddressBase::Register(Register::Rdx),
            index: None,
            scale: 1,
            displacement: 0,
            address_size: OperandSize::Qword,
            size,
        };
        let mut memory = Memory::new(&[0x65, 0x0f, 0xc1, 0x02, 0x01, 0xf0]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 4);
        assert_eq!(instruction.operand_size, OperandSize::Dword);
        assert_eq!(
            instruction.operation,
            Operation::XaddGsMem {
                destination: rdx(OperandSize::Dword),
                source: RegisterView::low(Register::Rax, OperandSize::Dword),
            }
        );
        assert_eq!(instruction.flag_effects().defined, crate::ARITHMETIC_FLAGS);
        assert_eq!(instruction.flag_effects().undefined, 0);
        // FS, the byte form (AL), and the word form in both prefix orders (CX).
        assert_eq!(
            Memory::new(&[0x64, 0x0f, 0xc1, 0x02])
                .decode()
                .unwrap()
                .operation,
            Operation::XaddFsMem {
                destination: rdx(OperandSize::Dword),
                source: RegisterView::low(Register::Rax, OperandSize::Dword),
            }
        );
        let byte = Memory::new(&[0x65, 0x0f, 0xc0, 0x02]).decode().unwrap();
        assert_eq!(byte.length, 4);
        assert_eq!(
            byte.operation,
            Operation::XaddGsMem {
                destination: rdx(OperandSize::Byte),
                source: RegisterView::decode_byte(0, false).unwrap(),
            }
        );
        for bytes in [
            &[0x65u8, 0x66, 0x0f, 0xc1, 0x0a][..],
            &[0x66, 0x65, 0x0f, 0xc1, 0x0a][..],
        ] {
            let word = Memory::new(bytes).decode().unwrap();
            assert_eq!(word.length, 5, "{bytes:02x?}");
            assert_eq!(
                word.operation,
                Operation::XaddGsMem {
                    destination: rdx(OperandSize::Word),
                    source: RegisterView::low(Register::Rcx, OperandSize::Word),
                },
                "{bytes:02x?}"
            );
        }
        // REX.B (`xaddb %al, %gs:0x1a(%r10)` is the kernel's `refresh_cpu_vm_stats` form).
        let rex = Memory::new(&[0x65, 0x41, 0x0f, 0xc0, 0x42, 0x1a])
            .decode()
            .unwrap();
        assert_eq!(rex.length, 6);
        assert_eq!(
            rex.operation,
            Operation::XaddGsMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::R10),
                    index: None,
                    scale: 1,
                    displacement: 0x1a,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Byte,
                },
                source: RegisterView::decode_byte(0, true).unwrap(),
            }
        );
        // RIP-relative word form of `choose_new_asid`.
        let rip_relative = Memory::new(&[0x65, 0x66, 0x0f, 0xc1, 0x0d, 0xa4, 0xb8, 0x01, 0x03])
            .decode()
            .unwrap();
        assert_eq!(rip_relative.length, 9);
        assert!(matches!(
            rip_relative.operation,
            Operation::XaddGsMem {
                destination: MemoryOperand {
                    base: AddressBase::NextRip,
                    size: OperandSize::Word,
                    ..
                },
                ..
            }
        ));

        // Refused with the opcode byte: the qword form, the register form, 0x66 with the byte
        // opcode, LOCK/REP/REPNE, 0x67, a second or a non-FS/GS segment byte next to FS/GS, and a
        // REX byte that is not directly before the opcode. The bare `0F C0` stays refused too.
        for (bytes, opcode) in [
            (&[0x65u8, 0x48, 0x0f, 0xc1, 0x02][..], 0xc1u8),
            (&[0x64, 0x48, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x66, 0x48, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x0f, 0xc1, 0xc2][..], 0xc1),
            (&[0x64, 0x0f, 0xc0, 0xc2][..], 0xc0),
            (&[0x65, 0x66, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0xf0, 0x65, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0xf0, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0xf3, 0x65, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0xf2, 0x64, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0x67, 0x65, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x67, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0x64, 0x65, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x3e, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x2e, 0x65, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0x41, 0x65, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x41, 0x66, 0x0f, 0xc1, 0x02][..], 0xc1),
            (&[0x65, 0x48, 0x40, 0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0x0f, 0xc0, 0x02][..], 0xc0),
            (&[0x66, 0x0f, 0xc0, 0x02][..], 0xc0),
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { opcode: refused, .. }) if refused.byte == opcode
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn ds_memory_cmpxchg_decodes_to_the_lock_operation_for_the_dword_and_qword_forms() {
        // S4-38L9h: `3E [REX] 0F B1 /r` with a memory destination is `LockCmpxchgMem` (the same
        // operation as `F0 [REX] 0F B1 /r`). The S4-38L9g diagnostic boundary: `ds cmpxchg
        // %edx, (%rdi)`.
        let mut memory = Memory::new(&[0x3e, 0x0f, 0xb1, 0x17]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 4);
        assert_eq!(instruction.prefixes.segment, Some(0x3e));
        assert_eq!(instruction.prefixes.group1, None);
        let dword = Operation::LockCmpxchgMem {
            destination: MemoryOperand {
                base: AddressBase::Register(Register::Rdi),
                index: None,
                scale: 1,
                displacement: 0,
                address_size: OperandSize::Qword,
                size: OperandSize::Dword,
            },
            source: RegisterView::low(Register::Rdx, OperandSize::Dword),
        };
        assert_eq!(instruction.operation, dword);
        assert_eq!(instruction.flag_effects().defined, crate::ARITHMETIC_FLAGS);
        // The LOCK form of the same instruction decodes to the identical operation.
        assert_eq!(
            Memory::new(&[0xf0, 0x0f, 0xb1, 0x17])
                .decode()
                .unwrap()
                .operation,
            dword
        );

        let mut memory = Memory::new(&[0x3e, 0x4c, 0x0f, 0xb1, 0x25, 0x34, 0x12, 0x00, 0x00]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 9);
        assert_eq!(
            instruction.operation,
            Operation::LockCmpxchgMem {
                destination: MemoryOperand {
                    base: AddressBase::NextRip,
                    index: None,
                    scale: 1,
                    displacement: 0x1234,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
                source: RegisterView::low(Register::R12, OperandSize::Qword),
            }
        );
        // REX without W (REX.R only): the dword form with an extended source.
        let mut memory = Memory::new(&[0x3e, 0x44, 0x0f, 0xb1, 0x0b]);
        assert_eq!(
            memory.decode().unwrap().operation,
            Operation::LockCmpxchgMem {
                destination: MemoryOperand {
                    base: AddressBase::Register(Register::Rbx),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Dword,
                },
                source: RegisterView::low(Register::R9, OperandSize::Dword),
            }
        );

        for bytes in [
            &[0x3e, 0x0f, 0xb1, 0xd1][..], // register destination
            &[0x3e, 0x48, 0x0f, 0xb1, 0xd1][..],
            &[0x3e, 0xf0, 0x0f, 0xb1, 0x17], // LOCK + DS, either order
            &[0xf0, 0x3e, 0x48, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x66, 0x0f, 0xb1, 0x17],
            &[0x66, 0x3e, 0x48, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x67, 0x0f, 0xb1, 0x17],
            &[0x3e, 0xf2, 0x48, 0x0f, 0xb1, 0x17],
            &[0xf3, 0x3e, 0x0f, 0xb1, 0x17],
            &[0x2e, 0x0f, 0xb1, 0x17], // CS/ES/SS (bare)
            &[0x26, 0x48, 0x0f, 0xb1, 0x17],
            &[0x36, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x3e, 0x48, 0x0f, 0xb1, 0x17], // repeated or mixed overrides
            &[0x2e, 0x3e, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x2e, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x64, 0x0f, 0xb1, 0x17],
            &[0x65, 0x3e, 0x48, 0x0f, 0xb1, 0x17],
            &[0x48, 0x3e, 0x0f, 0xb1, 0x17], // REX before DS or not before the opcode
            &[0x3e, 0x48, 0x40, 0x0f, 0xb1, 0x17],
            &[0x3e, 0x48, 0x66, 0x0f, 0xb1, 0x17],
            // S4-38L9k: `0f b1 17` (no prefix, dword memory) decodes now as `CmpxchgMemory`.
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { opcode, .. }) if opcode.byte == 0xb1
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn ds_forms_of_the_other_locked_memory_rmw_instructions_decode_to_memory_destination_rmw() {
        // S4-38L9h: the DS form of every other LOCK memory form of the set (ADD m, r; ADD/OR/AND
        // m, imm; INC/DEC; BTS/BTR) already decodes, through the plain operations, to a
        // read-modify-write on a memory operand; the DS byte is ignored (no segment base).
        // `ADD m, r` and the byte/dword/qword immediates (`80`/`81`/`83`), INC/DEC (`FF /0`, `/1`).
        let arithmetic: &[&[u8]] = &[
            &[0x3e, 0x01, 0x13],
            &[0x3e, 0x48, 0x01, 0x13],
            &[0x3e, 0x80, 0x03, 0x05],
            &[0x3e, 0x81, 0x03, 0x05, 0, 0, 0],
            &[0x3e, 0x83, 0x03, 0x05],
            &[0x3e, 0x48, 0x81, 0x03, 0x05, 0, 0, 0],
            &[0x3e, 0x48, 0x83, 0x03, 0x05],
            &[0x3e, 0xff, 0x03],
            &[0x3e, 0x48, 0xff, 0x03],
            &[0x3e, 0xff, 0x0b],
            &[0x3e, 0x48, 0xff, 0x0b],
        ];
        for bytes in arithmetic {
            assert!(
                matches!(
                    Memory::new(bytes).decode().unwrap().operation,
                    Operation::Arithmetic {
                        dst: Operand::Memory(_),
                        ..
                    }
                ),
                "{bytes:02x?}"
            );
        }
        let logic: &[&[u8]] = &[
            &[0x3e, 0x80, 0x0b, 0x01],
            &[0x3e, 0x81, 0x0b, 0x01, 0, 0, 0],
            &[0x3e, 0x83, 0x0b, 0x01],
            &[0x3e, 0x48, 0x83, 0x0b, 0x01],
            &[0x3e, 0x80, 0x23, 0xfe],
        ];
        for bytes in logic {
            assert!(
                matches!(
                    Memory::new(bytes).decode().unwrap().operation,
                    Operation::Logic {
                        dst: Operand::Memory(_),
                        ..
                    }
                ),
                "{bytes:02x?}"
            );
        }
        let bits: &[&[u8]] = &[
            &[0x3e, 0x48, 0x0f, 0xab, 0x13],
            &[0x3e, 0x48, 0x0f, 0xb3, 0x13],
            &[0x3e, 0x0f, 0xba, 0x2b, 0x05],
            &[0x3e, 0x48, 0x0f, 0xba, 0x2b, 0x45],
        ];
        for bytes in bits {
            assert!(
                matches!(
                    Memory::new(bytes).decode().unwrap().operation,
                    Operation::Bit {
                        dst: Operand::Memory(_),
                        ..
                    }
                ),
                "{bytes:02x?}"
            );
        }
        // The byte CMPXCHG (`0F B0`) has no LOCK form in the set and keeps its refusal with DS.
        assert!(matches!(
            Memory::new(&[0x3e, 0x0f, 0xb0, 0x17]).decode(),
            Err(DecodeError::Unsupported { opcode, .. }) if opcode.byte == 0xb0
        ));
    }

    #[test]
    fn qword_register_cmpxchg_decodes_only_the_bare_profile_form() {
        let mut memory = Memory::new(&[0x48, 0x0f, 0xb1, 0xd9]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.length, 4);
        assert_eq!(
            instruction.operation,
            Operation::Cmpxchg {
                destination: RegisterView::low(Register::Rcx, OperandSize::Qword),
                source: RegisterView::low(Register::Rbx, OperandSize::Qword),
            }
        );
        assert_eq!(instruction.flag_effects().defined, crate::ARITHMETIC_FLAGS);

        let mut extended = Memory::new(&[0x4d, 0x0f, 0xb1, 0xc8]);
        assert_eq!(
            extended.decode().unwrap().operation,
            Operation::Cmpxchg {
                destination: RegisterView::low(Register::R8, OperandSize::Qword),
                source: RegisterView::low(Register::R9, OperandSize::Qword),
            }
        );

        for bytes in [
            &[0x0f, 0xb1, 0xd9][..], // default dword width
            &[0x66, 0x48, 0x0f, 0xb1, 0xd9],
            &[0x67, 0x48, 0x0f, 0xb1, 0xd9],
            &[0x2e, 0x48, 0x0f, 0xb1, 0xd9],
            &[0xf0, 0x48, 0x0f, 0xb1, 0xd9],
            &[0xf3, 0x48, 0x0f, 0xb1, 0x18],
            // S4-38L9k: the default dword memory destination (`0f b1 18`) decodes now.
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn direct_call_and_ret_reject_prefixes_and_truncated_immediates() {
        for bytes in [
            &[0x66, 0xe8, 0, 0, 0, 0][..],
            // S4-38L7af: a lone CS/DS/ES/SS override is accepted; the rest stays refused.
            &[0x64, 0xe8, 0, 0, 0, 0][..],
            &[0x65, 0xe8, 0, 0, 0, 0][..],
            &[0x2e, 0x2e, 0xe8, 0, 0, 0, 0][..],
            &[0x2e, 0x64, 0xe8, 0, 0, 0, 0][..],
            &[0x2e, 0x66, 0xe8, 0, 0, 0, 0][..],
            &[0x2e, 0x48, 0xe8, 0, 0, 0, 0][..],
            &[0x48, 0x2e, 0xe8, 0, 0, 0, 0][..],
            &[0xf0, 0x2e, 0xe8, 0, 0, 0, 0][..],
            &[0x67, 0xe8, 0, 0, 0, 0][..],
            &[0x48, 0xe8, 0, 0, 0, 0][..],
            &[0xf3, 0xe8, 0, 0, 0, 0][..],
            &[0x48, 0xc3][..],
            &[0x2e, 0x66, 0xc3][..],
            &[0x66, 0x48, 0xc3][..],
            &[0x66, 0x66, 0xc3][..],
            &[0x66, 0xc2, 0, 0][..],
            &[0x48, 0xc2, 0, 0][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(
                matches!(memory.decode(), Err(DecodeError::Unsupported { .. })),
                "{bytes:02x?}"
            );
        }
        for bytes in [&[0xc2][..], &[0xc2, 0x34][..]] {
            let mut memory = Memory::new(bytes);
            assert!(matches!(memory.decode(), Err(DecodeError::Memory(_))));
            assert_eq!(memory.fetched.len(), bytes.len() + 1);
        }

        for bytes in [
            &[0xe8][..],
            &[0xe8, 0][..],
            &[0xe8, 0, 0][..],
            &[0xe8, 0, 0, 0][..],
            // S4-38L7af: the prefixed spelling is truncated the same way.
            &[0x2e, 0xe8][..],
            &[0x2e, 0xe8, 0][..],
            &[0x2e, 0xe8, 0, 0][..],
            &[0x2e, 0xe8, 0, 0, 0][..],
            &[0x3e, 0xe8, 0, 0, 0][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(
                matches!(memory.decode(), Err(DecodeError::Memory(_))),
                "{bytes:02x?}"
            );
        }

        for bytes in [&[0x66, 0xc3][..], &[0x48, 0x66, 0xc3][..]] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Qword);
            assert_eq!(instruction.operation, Operation::Return { stack_adjust: 0 });
        }
    }

    #[test]
    fn indirect_jump_decodes_registers_and_existing_memory_address_forms() {
        for (bytes, register) in [
            (&[0xff, 0xe0][..], Register::Rax),
            (&[0x41, 0xff, 0xe0][..], Register::R8),
            (&[0x49, 0xff, 0xe0][..], Register::R8),
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Qword);
            assert_eq!(
                instruction.operation,
                Operation::IndirectJump {
                    operand: Operand::Register(RegisterView::low(register, OperandSize::Qword))
                }
            );
        }

        for (bytes, expected) in [
            (
                &[0xff, 0x20][..],
                MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
            ),
            (
                &[0x41, 0xff, 0x20][..],
                MemoryOperand {
                    base: AddressBase::Register(Register::R8),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
            ),
            (
                &[0x67, 0xff, 0x20][..],
                MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Dword,
                    size: OperandSize::Qword,
                },
            ),
            (
                &[0xff, 0x64, 0x88, 0x10][..],
                MemoryOperand {
                    base: AddressBase::Register(Register::Rax),
                    index: Some(Register::Rcx),
                    scale: 4,
                    displacement: 0x10,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
            ),
            (
                &[0xff, 0x25, 0, 0, 0, 0][..],
                MemoryOperand {
                    base: AddressBase::NextRip,
                    index: None,
                    scale: 1,
                    displacement: 0,
                    address_size: OperandSize::Qword,
                    size: OperandSize::Qword,
                },
            ),
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(
                instruction.operation,
                Operation::IndirectJump {
                    operand: Operand::Memory(expected)
                },
                "{bytes:02x?}"
            );
            assert_eq!(instruction.length as usize, bytes.len());
        }

        for bytes in [
            &[0xff, 0xe8][..], // /5 far JMP
            &[0x66, 0xff, 0xe0],
            &[0x67, 0xff, 0xe0],
            &[0x2e, 0xff, 0xe0],
            &[0xf3, 0xff, 0xe0],
            &[0x64, 0xff, 0x20],
            &[0x65, 0xff, 0x20],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        for bytes in [
            &[0xff][..],
            &[0xff, 0x20][..],
            &[0xff, 0x24][..],
            &[0xff, 0x25][..],
        ] {
            let mut memory = Memory::new(bytes);
            if bytes.len() == 1 {
                assert!(matches!(memory.decode(), Err(DecodeError::Memory(_))));
            } else {
                let mut memory = Memory::new(bytes);
                memory.fault_at = Some(1);
                assert!(matches!(memory.decode(), Err(DecodeError::Memory(_))));
            }
        }
    }

    #[test]
    fn indirect_call_decodes_register_and_ordinary_memory_r64_forms() {
        for (bytes, register) in [
            (&[0xff, 0xd0][..], Register::Rax),
            (&[0x41, 0xff, 0xd0][..], Register::R8),
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Qword);
            assert_eq!(
                instruction.operation,
                Operation::IndirectCall {
                    operand: Operand::Register(RegisterView::low(register, OperandSize::Qword))
                }
            );
        }

        for bytes in [
            &[0xff, 0x10][..],             // [RAX]
            &[0x41, 0xff, 0x10][..],       // [R8]
            &[0xff, 0x54, 0x88, 0x10][..], // [RAX + RCX*4 + 0x10]
            &[0xff, 0x15, 0, 0, 0, 0][..], // RIP-relative
            &[0x67, 0xff, 0x10][..],       // 32-bit address size
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Qword);
            assert!(matches!(
                instruction.operation,
                Operation::IndirectCall {
                    operand: Operand::Memory(MemoryOperand {
                        size: OperandSize::Qword,
                        ..
                    })
                }
            ));
        }

        for bytes in [
            &[0xff, 0xd8][..], // far /3
            &[0x48, 0xff, 0xd0][..],
            &[0x40, 0xff, 0xd0][..],
            &[0x66, 0xff, 0xd0][..],
            &[0x67, 0xff, 0xd0][..],
            &[0xf3, 0xff, 0xd0][..],
            &[0xf0, 0xff, 0x10][..], // LOCK memory CALL
            &[0x64, 0xff, 0x10][..], // FS-relative profile is unsupported
            &[0x66, 0xff, 0x10][..], // 16-bit operand override
        ] {
            let mut memory = Memory::new(bytes);
            assert!(
                matches!(memory.decode(), Err(DecodeError::Unsupported { .. })),
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn memory_push_decodes_qword_base_sib_rip_relative_and_address32_forms() {
        for bytes in [
            &[0xff, 0x30][..],             // [RAX]
            &[0x41, 0xff, 0x30][..],       // [R8]
            &[0xff, 0x34, 0x8b][..],       // [RBX + RCX*4]
            &[0xff, 0x35, 0, 0, 0, 0][..], // RIP-relative
            &[0x67, 0xff, 0x30][..],       // [EAX]
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Qword);
            assert!(
                matches!(
                    instruction.operation,
                    Operation::PushMemory {
                        source: MemoryOperand {
                            size: OperandSize::Qword,
                            ..
                        }
                    }
                ),
                "decoded {bytes:02x?} as {instruction:?}"
            );
        }

        for bytes in [
            &[0x66, 0xff, 0x30][..],             // word [RAX]
            &[0x66, 0x41, 0xff, 0x30][..],       // word [R8]
            &[0x66, 0xff, 0x34, 0x8b][..],       // word [RBX + RCX*4]
            &[0x66, 0xff, 0x35, 0, 0, 0, 0][..], // word RIP-relative
            &[0x67, 0x66, 0xff, 0x30][..],       // word [EAX]
            &[0x66, 0xff, 0x34, 0x24][..],       // word [RSP]
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len());
            assert_eq!(instruction.operand_size, OperandSize::Word);
            assert!(
                matches!(
                    instruction.operation,
                    Operation::PushMemory {
                        source: MemoryOperand {
                            size: OperandSize::Word,
                            ..
                        }
                    }
                ),
                "decoded {bytes:02x?} as {instruction:?}"
            );
        }

        for bytes in [
            &[0xff, 0xf0][..],       // register mode is not PUSH r/m
            &[0xf0, 0xff, 0x30][..], // LOCK
            &[0x64, 0xff, 0x30][..], // FS
            &[0x65, 0xff, 0x30][..], // GS
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        let instruction = Memory::new(&[0x66, 0x48, 0xff, 0x30]).decode().unwrap();
        assert_eq!(instruction.operand_size, OperandSize::Qword);
        assert!(matches!(
            instruction.operation,
            Operation::PushMemory {
                source: MemoryOperand {
                    size: OperandSize::Qword,
                    ..
                }
            }
        ));
        for (bytes, expected_size) in [
            (&[0x66, 0x40, 0x48, 0xff, 0x30][..], OperandSize::Qword),
            (&[0x66, 0x48, 0x40, 0xff, 0x30][..], OperandSize::Word),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.operand_size, expected_size, "{bytes:02x?}");
        }
    }

    #[test]
    fn fxsave_rip_profile_decodes_only_plain_exact_form_and_fetches_disp32_on_demand() {
        let observed = [0x0f, 0xae, 0x05, 0x6b, 0xf9, 0x17, 0x00];
        let mut decoded = Memory::new(&observed);
        let instruction = decoded.decode().unwrap();
        assert_eq!(instruction.length, 7);
        assert_eq!(instruction.prefixes, Prefixes::default());
        assert_eq!(
            instruction.operation,
            Operation::FxsaveRipRelative(MemoryOperand {
                base: AddressBase::NextRip,
                index: None,
                scale: 1,
                displacement: 0x17_f96b,
                address_size: OperandSize::Qword,
                size: OperandSize::Qword,
            })
        );
        for bytes in [
            &[0x48, 0x0f, 0xae, 0x05, 0, 0, 0, 0][..],
            &[0x66, 0x0f, 0xae, 0x05, 0, 0, 0, 0][..],
            &[0x67, 0x0f, 0xae, 0x05, 0, 0, 0, 0][..],
            &[0xf3, 0x0f, 0xae, 0x05, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x00, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x04, 0x25, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x0d, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x15, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x1d, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x25, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x2d, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x35, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x3d, 0, 0, 0, 0][..],
            &[0x0f, 0xae, 0x45, 0][..],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. }) | Err(DecodeError::Memory(_))
                ),
                "{bytes:02x?}"
            );
        }

        for available in 3..7 {
            let mut truncated = Memory::new(&observed[..available]);
            assert!(matches!(
                truncated.decode(),
                Err(DecodeError::Memory(MemoryError::Unmapped {
                    access: AccessKind::Fetch,
                    ..
                }))
            ));
            assert_eq!(truncated.fetched.len(), available + 1);
        }
    }

