    #[test]
    fn repe_scas_word_dword_qword_prefix_normalization_is_exact() {
        for (bytes, size) in [
            (vec![0xf3, 0x66, 0xaf], OperandSize::Word),
            (vec![0xf3, 0xaf], OperandSize::Dword),
            (vec![0xf3, 0x48, 0xaf], OperandSize::Qword),
            (vec![0xf3, 0x48, 0x66, 0xaf], OperandSize::Word),
            (vec![0xf3, 0x66, 0x48, 0xaf], OperandSize::Qword),
        ] {
            assert_eq!(
                Memory::new(&bytes).decode().unwrap().operation,
                Operation::RepScas { size },
                "{bytes:02x?}"
            );
        }
        for rex in 0x48..=0x4f {
            assert_eq!(
                Memory::new(&[0xf3, rex, 0xaf]).decode().unwrap().operation,
                Operation::RepScas {
                    size: OperandSize::Qword
                }
            );
        }

        let streams = [
            vec![0xf3, 0x66, 0xaf],
            vec![0xf3, 0xaf],
            vec![0xf3, 0x48, 0xaf],
        ];
        let mut rejected = Vec::new();
        for stream in streams {
            for prefix in [0xf0, 0xf2, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65] {
                let mut bytes = vec![prefix];
                bytes.extend_from_slice(&stream);
                rejected.push(bytes);
            }
        }
        rejected.extend([
            vec![0xf3, 0x40, 0xaf],
            vec![0xf3, 0x47, 0xaf],
            vec![0xf3, 0x66, 0x66, 0xaf],
            vec![0xf3, 0x66, 0x40, 0xaf],
            vec![0xf3, 0x66, 0x47, 0xaf],
        ]);
        assert_eq!(rejected.len(), 29);
        for bytes in rejected {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "unexpected admission: {bytes:02x?}"
            );
        }
    }

    #[test]
    fn rep_cmps_admits_exact_widths_and_rejects_the_prefix_boundary() {
        assert_eq!(
            Memory::new(&[0xf3, 0xa6]).decode().unwrap().operation,
            Operation::RepCmps {
                size: OperandSize::Byte
            }
        );
        for bytes in [&[0xf3, 0x67, 0xa6][..], &[0x67, 0xf3, 0xa6][..]] {
            let decoded = Memory::new(bytes).decode().unwrap();
            assert_eq!(
                decoded.operation,
                Operation::RepCmps {
                    size: OperandSize::Byte
                }
            );
            assert_eq!(decoded.address_size, OperandSize::Dword);
            assert_eq!(decoded.length, 3);
        }
        for (bytes, size) in [
            (&[0xf3, 0x66, 0xa7][..], OperandSize::Word),
            (&[0x66, 0xf3, 0xa7][..], OperandSize::Word),
            (&[0xf3, 0xa7][..], OperandSize::Dword),
            (&[0xf3, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0xf3, 0x48, 0x66, 0xa7][..], OperandSize::Word),
            (&[0xf3, 0x66, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0xf3, 0x67, 0x66, 0xa7][..], OperandSize::Word),
            (&[0x67, 0xf3, 0x66, 0xa7][..], OperandSize::Word),
            (&[0xf3, 0x67, 0xa7][..], OperandSize::Dword),
            (&[0x67, 0xf3, 0xa7][..], OperandSize::Dword),
            (&[0xf3, 0x67, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0x67, 0xf3, 0x4f, 0xa7][..], OperandSize::Qword),
            (&[0xf3, 0x67, 0x48, 0x66, 0xa7][..], OperandSize::Word),
            (&[0xf3, 0x48, 0x67, 0x66, 0xa7][..], OperandSize::Word),
            (&[0xf3, 0x67, 0x66, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0x66, 0xf3, 0x67, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0xf3, 0x48, 0x67, 0xa7][..], OperandSize::Dword),
        ] {
            let decoded = Memory::new(bytes).decode().unwrap();
            assert_eq!(
                decoded.operation,
                Operation::RepCmps { size },
                "{bytes:02x?}"
            );
            assert_eq!(
                decoded.address_size,
                if bytes.contains(&0x67) {
                    OperandSize::Dword
                } else {
                    OperandSize::Qword
                },
                "{bytes:02x?}"
            );
        }
        for rex in 0x48..=0x4f {
            assert_eq!(
                Memory::new(&[0xf3, rex, 0xa7]).decode().unwrap().operation,
                Operation::RepCmps {
                    size: OperandSize::Qword
                }
            );
        }
        let mut rejected = Vec::new();
        for prefix in [0xf0, 0xf2, 0xf3, 0x66, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65] {
            rejected.push(vec![prefix, 0xf3, 0xa6]);
        }
        rejected.extend([
            vec![0xf3, 0x66, 0xa6],
            vec![0xf3, 0x67, 0x66, 0xa6],
            vec![0xf3, 0x67, 0x48, 0xa6],
            vec![0xf3, 0x67, 0xf3, 0xa6],
            vec![0xf3, 0x67, 0x67, 0xa7],
            vec![0xf3, 0xf3, 0x67, 0xa7],
            vec![0xf3, 0xf2, 0x67, 0xa7],
            vec![0xf3, 0xf0, 0x67, 0xa7],
            vec![0xf3, 0x26, 0x67, 0xa7],
            vec![0xf3, 0x67, 0x26, 0xa7],
            vec![0xf3, 0x67, 0x66, 0x66, 0xa7],
            vec![0xf3, 0x67, 0x40, 0xa7],
            vec![0xf3, 0x67, 0x47, 0xa7],
        ]);
        for rex in 0x40..=0x4f {
            rejected.push(vec![0xf3, rex, 0xa6]);
            if rex & 8 == 0 {
                rejected.push(vec![0xf3, 0x67, rex, 0xa7]);
                rejected.push(vec![0xf3, 0x67, 0x66, rex, 0xa7]);
            }
        }
        rejected.extend([vec![0xf2, 0xa6], vec![0xf3, 0x66, 0xa6], vec![0xf2, 0xa7]]);
        for bytes in rejected {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        let mut rejected = Vec::new();
        for form in [
            vec![0xf3, 0x66, 0xa7],
            vec![0xf3, 0xa7],
            vec![0xf3, 0x48, 0xa7],
        ] {
            for prefix in [0xf0, 0xf2, 0xf3, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65] {
                rejected.push([vec![prefix], form.clone()].concat());
            }
        }
        rejected.extend([
            vec![0xf3, 0x40, 0xa7],
            vec![0xf3, 0x47, 0xa7],
            vec![0xf3, 0x66, 0x66, 0xa7],
            vec![0xf3, 0x66, 0x40, 0xa7],
            vec![0xf3, 0x66, 0x47, 0xa7],
            vec![0xf3, 0x67, 0x67, 0xa7],
            vec![0xf3, 0xf3, 0x67, 0xa7],
            vec![0xf3, 0xf2, 0x67, 0xa7],
            vec![0xf3, 0xf0, 0x67, 0xa7],
            vec![0xf3, 0x67, 0x26, 0xa7],
            vec![0xf3, 0x67, 0x66, 0x66, 0xa7],
            vec![0xf3, 0x67, 0x40, 0xa7],
            vec![0xf3, 0x67, 0x47, 0xa7],
        ]);
        for bytes in rejected {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        for rex in 0x40..=0x47 {
            for bytes in [vec![0xf3, rex, 0xa7], vec![0xf3, 0x66, rex, 0xa7]] {
                assert!(
                    matches!(
                        Memory::new(&bytes).decode(),
                        Err(DecodeError::Unsupported { .. })
                    ),
                    "non-W REX was admitted: {bytes:02x?}"
                );
            }
        }
    }

    #[test]
    fn non_rep_cmps_admits_addr32_widths_and_rejects_the_prefix_boundary() {
        for (bytes, size) in [
            (&[0x67, 0xa6][..], OperandSize::Byte),
            (&[0x67, 0x66, 0xa7][..], OperandSize::Word),
            (&[0x67, 0xa7][..], OperandSize::Dword),
            (&[0x67, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0x67, 0x48, 0x66, 0xa7][..], OperandSize::Word),
            (&[0x67, 0x66, 0x48, 0xa7][..], OperandSize::Qword),
            (&[0x48, 0x67, 0xa7][..], OperandSize::Dword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(
                instruction.operation,
                Operation::Cmps { size },
                "{bytes:02x?}"
            );
            assert_eq!(instruction.address_size, OperandSize::Dword, "{bytes:02x?}");
        }
        for rex in 0x48..=0x4f {
            let bytes = [0x67, rex, 0xa7];
            assert_eq!(
                Memory::new(&bytes).decode().unwrap().operation,
                Operation::Cmps {
                    size: OperandSize::Qword
                },
                "{bytes:02x?}"
            );
        }

        let forms = [
            vec![0x67, 0xa6],
            vec![0x67, 0x66, 0xa7],
            vec![0x67, 0xa7],
            vec![0x67, 0x48, 0xa7],
        ];
        let mut rejected = Vec::new();
        for form in &forms {
            for prefix in [0xf0, 0xf2, 0xf3, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65] {
                if prefix == 0xf2 && (*form == [0x67, 0xa6] || form.last() == Some(&0xa7)) {
                    continue;
                }
                if prefix == 0xf3 && (*form == [0x67, 0xa6] || form.last() == Some(&0xa7)) {
                    continue;
                }
                rejected.push([vec![prefix], form.clone()].concat());
            }
            rejected.push([vec![0x67], form.clone()].concat());
        }
        rejected.push(vec![0x67, 0x66, 0xa6]);
        for rex in 0x40..=0x4f {
            rejected.push(vec![0x67, rex, 0xa6]);
        }
        for rex in 0x40..=0x47 {
            rejected.push(vec![0x67, rex, 0xa7]);
            rejected.push(vec![0x67, 0x66, rex, 0xa7]);
        }
        assert_eq!(rejected.len(), 65);
        for bytes in rejected {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }

        for (bytes, size) in [
            (&[0x67, 0xf3, 0x66, 0xa7][..], OperandSize::Word),
            (&[0x67, 0xf3, 0xa7][..], OperandSize::Dword),
        ] {
            assert_eq!(
                Memory::new(bytes).decode().unwrap().operation,
                Operation::RepCmps { size },
                "{bytes:02x?}"
            );
        }
    }

    #[test]
    fn rep_movs_decodes_exact_widths_and_normalized_prefix_ordering() {
        for (bytes, size) in [
            (&[0xf3, 0xa4][..], OperandSize::Byte),
            (&[0xf3, 0x66, 0xa5][..], OperandSize::Word),
            (&[0x66, 0xf3, 0xa5][..], OperandSize::Word),
            (&[0xf3, 0xa5][..], OperandSize::Dword),
            (&[0xf3, 0x48, 0xa5][..], OperandSize::Qword),
            (&[0xf3, 0x48, 0x66, 0xa5][..], OperandSize::Word),
            (&[0xf3, 0x66, 0x48, 0xa5][..], OperandSize::Qword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(
                instruction.operation,
                Operation::RepMovs { size },
                "{bytes:02x?}"
            );
        }
        for rex in 0x48..=0x4f {
            assert_eq!(
                Memory::new(&[0xf3, rex, 0xa5]).decode().unwrap().operation,
                Operation::RepMovs {
                    size: OperandSize::Qword
                }
            );
        }
        let forms: [&[u8]; 4] = [
            &[0xf3, 0xa4],
            &[0xf3, 0x66, 0xa5],
            &[0xf3, 0xa5],
            &[0xf3, 0x48, 0xa5],
        ];
        let prefixes: [&[u8]; 9] = [
            &[0xf0],
            &[0xf2],
            &[0x26],
            &[0x2e],
            &[0x36],
            &[0x3e],
            &[0x64],
            &[0x65],
            &[0xf3],
        ];
        let mut rejected = 0;
        for form in forms {
            for prefix in prefixes {
                let bytes = [prefix, form].concat();
                assert!(
                    matches!(
                        Memory::new(&bytes).decode(),
                        Err(DecodeError::Unsupported { .. })
                    ),
                    "{bytes:02x?}"
                );
                rejected += 1;
            }
        }
        let extras: [&[u8]; 8] = [
            &[0xf3, 0x66, 0xa4],
            &[0xf3, 0x40, 0xa4],
            &[0xf3, 0x48, 0xa4],
            &[0xf3, 0x40, 0xa5],
            &[0xf3, 0x47, 0xa5],
            &[0xf3, 0x66, 0x66, 0xa5],
            &[0xf3, 0x66, 0x40, 0xa5],
            &[0xf3, 0x66, 0x47, 0xa5],
        ];
        for bytes in extras {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
            rejected += 1;
        }
        assert_eq!(rejected, 44);
    }

    #[test]
    fn rep_stos_address32_decodes_bounded_widths_and_normalized_prefixes() {
        for (bytes, size) in [
            (&[0xf3, 0x67, 0xaa][..], OperandSize::Byte),
            (&[0xf3, 0x67, 0x66, 0xab][..], OperandSize::Word),
            (&[0xf3, 0x67, 0xab][..], OperandSize::Dword),
            (&[0xf3, 0x67, 0x48, 0xab][..], OperandSize::Qword),
            (&[0xf3, 0x66, 0x67, 0xab][..], OperandSize::Word),
            (&[0xf3, 0x67, 0x48, 0x66, 0xab][..], OperandSize::Word),
            (&[0xf3, 0x67, 0x66, 0x48, 0xab][..], OperandSize::Qword),
            (&[0xf3, 0x48, 0x67, 0xab][..], OperandSize::Dword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(
                instruction.operation,
                Operation::RepStos { size },
                "{bytes:02x?}"
            );
            assert_eq!(instruction.address_size, OperandSize::Dword, "{bytes:02x?}");
        }
        for rex in 0x48..=0x4f {
            let bytes = [0xf3, 0x67, rex, 0xab];
            assert_eq!(
                Memory::new(&bytes).decode().unwrap().operation,
                Operation::RepStos {
                    size: OperandSize::Qword
                },
                "{bytes:02x?}"
            );
        }
        assert_eq!(
            Memory::new(&[0x67, 0xf3, 0xaa]).decode().unwrap().operation,
            Operation::RepStos {
                size: OperandSize::Byte
            }
        );

        let forms: [&[u8]; 4] = [
            &[0xf3, 0x67, 0xaa],
            &[0xf3, 0x67, 0x66, 0xab],
            &[0xf3, 0x67, 0xab],
            &[0xf3, 0x67, 0x48, 0xab],
        ];
        let mut rejected = Vec::new();
        for form in forms {
            for prefix in [0xf0, 0xf2, 0x26, 0x2e, 0x36, 0x3e, 0x64, 0x65] {
                rejected.push([vec![prefix], form.to_vec()].concat());
            }
            rejected.push([vec![0x67], form.to_vec()].concat());
        }
        rejected.extend([
            vec![0xf3, 0x67, 0x66, 0xaa],
            vec![0xf3, 0x67, 0x48, 0xaa],
            vec![0xf3, 0x67, 0x66, 0x66, 0xab],
            vec![0xf3, 0x67, 0x48, 0x40, 0xab],
            vec![0xf3, 0x67, 0x48, 0x47, 0xab],
        ]);
        for rex in 0x40..=0x4f {
            rejected.push(vec![0xf3, 0x67, rex, 0xaa]);
        }
        for rex in 0x40..=0x47 {
            rejected.push(vec![0xf3, 0x67, rex, 0xab]);
            rejected.push(vec![0xf3, 0x67, 0x66, rex, 0xab]);
        }
        assert_eq!(rejected.len(), 73);
        for bytes in rejected {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

