    #[test]
    fn rep_lods_decodes_widths_and_normalized_prefix_ordering() {
        for (bytes, size) in [
            (&[0xf3, 0xac][..], OperandSize::Byte),
            (&[0xf3, 0x66, 0xad][..], OperandSize::Word),
            (&[0x66, 0xf3, 0xad][..], OperandSize::Word),
            (&[0xf3, 0xad][..], OperandSize::Dword),
            (&[0xf3, 0x48, 0xad][..], OperandSize::Qword),
            (&[0xf3, 0x48, 0x66, 0xad][..], OperandSize::Word),
            (&[0xf3, 0x66, 0x48, 0xad][..], OperandSize::Qword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.operand_size, size, "{bytes:02x?}");
            assert_eq!(
                instruction.operation,
                Operation::RepLods { size },
                "{bytes:02x?}"
            );
        }
        for rex in 0x48..=0x4f {
            let instruction = Memory::new(&[0xf3, rex, 0xad]).decode().unwrap();
            assert_eq!(
                instruction.operation,
                Operation::RepLods {
                    size: OperandSize::Qword
                }
            );
        }
        for (bytes, size) in [
            (&[0xf3, 0x67, 0xac][..], OperandSize::Byte),
            (&[0xf3, 0x67, 0x66, 0xad][..], OperandSize::Word),
            (&[0xf3, 0x67, 0xad][..], OperandSize::Dword),
            (&[0xf3, 0x67, 0x48, 0xad][..], OperandSize::Qword),
            (&[0xf3, 0x66, 0x67, 0xad][..], OperandSize::Word),
            (&[0xf3, 0x67, 0x48, 0x66, 0xad][..], OperandSize::Word),
            (&[0xf3, 0x67, 0x66, 0x48, 0xad][..], OperandSize::Qword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.address_size, OperandSize::Dword, "{bytes:02x?}");
            assert_eq!(instruction.operand_size, size, "{bytes:02x?}");
            assert_eq!(
                instruction.operation,
                Operation::RepLods { size },
                "{bytes:02x?}"
            );
        }
        assert!(matches!(
            Memory::new(&[0xf3, 0x66, 0xac]).decode(),
            Err(DecodeError::Unsupported { .. })
        ));
        assert!(matches!(
            Memory::new(&[0x48, 0xf3, 0xac]).decode(),
            Err(DecodeError::Unsupported { .. })
        ));

        let forms: [&[u8]; 4] = [
            &[0xf3, 0xac],
            &[0xf3, 0x66, 0xad],
            &[0xf3, 0xad],
            &[0xf3, 0x48, 0xad],
        ];
        let prefixes: [&[u8]; 9] = [
            &[0xf0],
            &[0xf2],
            &[0x26],
            &[0x2e],
            &[0x36],
            &[0x3e],
            &[0x64],
            &[0x65],
            &[0xf3],
        ];
        let mut rejected = 0;
        for form in forms {
            for prefix in prefixes {
                let bytes = [prefix, form].concat();
                assert!(
                    matches!(
                        Memory::new(&bytes).decode(),
                        Err(DecodeError::Unsupported { .. })
                    ),
                    "{bytes:02x?}"
                );
                rejected += 1;
            }
        }
        let extras: [&[u8]; 8] = [
            &[0xf3, 0x66, 0xac],
            &[0xf3, 0x40, 0xac],
            &[0xf3, 0x48, 0xac],
            &[0xf3, 0x40, 0xad],
            &[0xf3, 0x47, 0xad],
            &[0xf3, 0x66, 0x66, 0xad],
            &[0xf3, 0x66, 0x40, 0xad],
            &[0xf3, 0x66, 0x47, 0xad],
        ];
        for bytes in extras {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
            rejected += 1;
        }
        assert_eq!(rejected, 44);
    }

    #[test]
    fn stos_ab_decodes_bounded_widths_and_rex_66_ordering() {
        for (bytes, size) in [
            (&[0xaa][..], OperandSize::Byte),
            (&[0x66, 0xab][..], OperandSize::Word),
            (&[0xab][..], OperandSize::Dword),
            (&[0x48, 0xab][..], OperandSize::Qword),
            (&[0x66, 0x48, 0xab][..], OperandSize::Qword),
            (&[0x48, 0x66, 0xab][..], OperandSize::Word),
            (&[0x67, 0xaa][..], OperandSize::Byte),
            (&[0x67, 0x66, 0xab][..], OperandSize::Word),
            (&[0x67, 0xab][..], OperandSize::Dword),
            (&[0x67, 0x48, 0xab][..], OperandSize::Qword),
            (&[0x66, 0x67, 0xab][..], OperandSize::Word),
            (&[0x67, 0x48, 0x66, 0xab][..], OperandSize::Word),
            (&[0x48, 0x67, 0xab][..], OperandSize::Dword),
            (&[0x67, 0x66, 0x48, 0xab][..], OperandSize::Qword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len(), "{bytes:02x?}");
            assert_eq!(instruction.operand_size, size, "{bytes:02x?}");
            assert_eq!(
                instruction.address_size,
                if bytes.contains(&0x67) {
                    OperandSize::Dword
                } else {
                    OperandSize::Qword
                },
                "{bytes:02x?}"
            );
            assert_eq!(
                instruction.operation,
                Operation::Stos { size },
                "{bytes:02x?}"
            );
        }

        for rex in 0x48..=0x4f {
            for bytes in [
                vec![rex, 0xab],
                vec![0x66, rex, 0xab],
                vec![0x67, rex, 0xab],
                vec![0x67, 0x66, rex, 0xab],
            ] {
                let instruction = Memory::new(&bytes).decode().unwrap();
                assert_eq!(instruction.operand_size, OperandSize::Qword, "{bytes:02x?}");
                assert_eq!(
                    instruction.address_size,
                    if bytes.contains(&0x67) {
                        OperandSize::Dword
                    } else {
                        OperandSize::Qword
                    },
                    "{bytes:02x?}"
                );
                assert_eq!(
                    instruction.operation,
                    Operation::Stos {
                        size: OperandSize::Qword
                    }
                );
            }
            let ignored_rex = Memory::new(&[rex, 0x66, 0xab]).decode().unwrap();
            assert_eq!(ignored_rex.operand_size, OperandSize::Word);
            assert_eq!(
                ignored_rex.operation,
                Operation::Stos {
                    size: OperandSize::Word
                }
            );
        }
        let ignored_addr32_rex = Memory::new(&[0x67, 0x48, 0x66, 0xab]).decode().unwrap();
        assert_eq!(ignored_addr32_rex.address_size, OperandSize::Dword);
        assert_eq!(ignored_addr32_rex.operand_size, OperandSize::Word);
    }

    #[test]
    fn stos_address32_rejects_the_explicit_prefix_boundary_matrix() {
        let forms: [&[u8]; 4] = [
            &[0x67, 0xaa],
            &[0x67, 0x66, 0xab],
            &[0x67, 0xab],
            &[0x67, 0x48, 0xab],
        ];
        let prefixes: [&[u8]; 8] = [
            &[0xf0],
            &[0xf2],
            &[0x26],
            &[0x2e],
            &[0x36],
            &[0x3e],
            &[0x64],
            &[0x65],
        ];
        let mut cases = Vec::new();
        for form in forms {
            for prefix in prefixes {
                cases.push([prefix, form].concat());
            }
        }
        for form in forms {
            cases.push([&[0x67][..], form].concat());
        }
        cases.push(vec![0x67, 0x66, 0xaa]);
        for rex in 0x40..=0x4f {
            cases.push(vec![0x67, rex, 0xaa]);
        }
        for rex in 0x40..=0x47 {
            cases.push(vec![0x67, rex, 0xab]);
            cases.push(vec![0x67, 0x66, rex, 0xab]);
        }
        assert_eq!(cases.len(), 69);
        for bytes in cases {
            assert!(
                matches!(
                    Memory::new(&bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "unexpected admission: {bytes:02x?}"
            );
        }
    }

    #[test]
    fn scas_address32_decodes_only_the_bounded_nonrep_forms() {
        for (bytes, size) in [
            (&[0x67, 0xae][..], OperandSize::Byte),
            (&[0x67, 0x66, 0xaf][..], OperandSize::Word),
            (&[0x67, 0xaf][..], OperandSize::Dword),
            (&[0x67, 0x48, 0xaf][..], OperandSize::Qword),
            (&[0x66, 0x67, 0xaf][..], OperandSize::Word),
            (&[0x67, 0x48, 0x66, 0xaf][..], OperandSize::Word),
            (&[0x48, 0x67, 0xaf][..], OperandSize::Dword),
            (&[0x67, 0x66, 0x48, 0xaf][..], OperandSize::Qword),
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.length as usize, bytes.len(), "{bytes:02x?}");
            assert_eq!(instruction.operand_size, size, "{bytes:02x?}");
            assert_eq!(instruction.address_size, OperandSize::Dword, "{bytes:02x?}");
            assert_eq!(
                instruction.operation,
                Operation::Scas { size },
                "{bytes:02x?}"
            );
        }

        for rex in (0x40..=0x4f).filter(|rex| rex & 8 != 0) {
            for bytes in [vec![0x67, rex, 0xaf], vec![0x67, 0x66, rex, 0xaf]] {
                let instruction = Memory::new(&bytes).decode().unwrap();
                assert_eq!(instruction.operand_size, OperandSize::Qword, "{bytes:02x?}");
                assert_eq!(instruction.address_size, OperandSize::Dword, "{bytes:02x?}");
                assert_eq!(
                    instruction.operation,
                    Operation::Scas {
                        size: OperandSize::Qword
                    }
                );
            }
        }

        for bytes in [
            &[0xae][..],
            &[0x66, 0xaf][..],
            &[0xaf][..],
            &[0x48, 0xaf][..],
        ] {
            let instruction = Memory::new(bytes).decode().unwrap();
            assert_eq!(instruction.address_size, OperandSize::Qword, "{bytes:02x?}");
            assert!(matches!(instruction.operation, Operation::Scas { .. }));
        }
    }

