    #[test]
    fn mov_cr3_r64_decodes_every_source_with_any_rex_but_r() {
        // S4-38L7h: the bare `0F 22 D8` keeps `WriteCr3`; every other form
        // (any REX without R, any rm, REX.B) is `WriteCr3From`.
        for rex in [
            None,
            Some(0x40u8),
            Some(0x41),
            Some(0x48),
            Some(0x49),
            Some(0x4a),
            Some(0x4b),
        ] {
            for rm in 0u8..8 {
                let mut bytes = Vec::new();
                bytes.extend(rex);
                bytes.extend_from_slice(&[0x0f, 0x22, 0xd8 | rm]);
                let instruction = Memory::new(&bytes).decode().unwrap();
                let src = Register::from_encoding(rm | ((rex.unwrap_or(0) & 1) << 3)).unwrap();
                let expected = if rex.is_none() && rm == 0 {
                    Operation::WriteCr3
                } else {
                    Operation::WriteCr3From(src)
                };
                assert_eq!(instruction.operation, expected, "{bytes:02x?}");
                assert_eq!(instruction.length as usize, bytes.len());
                assert_eq!(instruction.operand_size, OperandSize::Qword);
                assert_eq!(instruction.prefixes.rex, rex);
            }
        }
        assert_eq!(
            Memory::new(&[0x0f, 0x22, 0xdf]).decode().unwrap().operation,
            Operation::WriteCr3From(Register::Rdi)
        );
        assert_eq!(
            Memory::new(&[0x0f, 0x22, 0xdb]).decode().unwrap().operation,
            Operation::WriteCr3From(Register::Rbx)
        );
        assert_eq!(
            Memory::new(&[0x41, 0x0f, 0x22, 0xd8])
                .decode()
                .unwrap()
                .operation,
            Operation::WriteCr3From(Register::R8)
        );
        assert_eq!(
            Memory::new(&[0x41, 0x0f, 0x22, 0xdf])
                .decode()
                .unwrap()
                .operation,
            Operation::WriteCr3From(Register::R15)
        );
        for bytes in [
            &[0x44, 0x0f, 0x22, 0xdf][..], // REX.R: CR11
            &[0x4d, 0x0f, 0x22, 0xdf][..],
            &[0x0f, 0x22, 0x1f][..], // mod != 11: conservative refusal (SDM not verified)
            &[0x0f, 0x22, 0x5f, 0x08][..],
            &[0x0f, 0x22, 0x9f, 0, 0, 0, 0][..],
            &[0x66, 0x0f, 0x22, 0xdf][..],
            &[0xf2, 0x0f, 0x22, 0xdf][..],
            &[0xf3, 0x0f, 0x22, 0xdf][..],
            &[0x67, 0x0f, 0x22, 0xdf][..],
            &[0x2e, 0x0f, 0x22, 0xdf][..],
            &[0xf0, 0x0f, 0x22, 0xdf][..], // LOCK with a non-RAX source: unsupported
            &[0x41, 0x66, 0x0f, 0x22, 0xdf][..],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        // The LOCK form of the bare RAX write keeps its own refusal (S4-38L4 family).
        assert!(matches!(
            Memory::new(&[0xf0, 0x0f, 0x22, 0xd8]).decode(),
            Err(DecodeError::InvalidMovCr3Lock { .. })
        ));
    }

    /// S4-38L9d: `0F 22 C7` (the `native_write_cr0` encoding, `MOV CR0, RDI`) decodes to
    /// `WriteCr0Rdi`; every other register source and every prefixed form stays unsupported.
    #[test]
    fn mov_cr0_rdi_decodes_only_as_the_exact_prefix_free_form() {
        let mut memory = Memory::new(&[0x0f, 0x22, 0xc7]);
        let instruction = memory.decode().unwrap();
        assert_eq!(instruction.operation, Operation::WriteCr0Rdi);
        assert_eq!(instruction.length, 3);
        assert_eq!(instruction.prefixes, Prefixes::default());
        assert_eq!(instruction.opcode.byte, 0x22);
        assert_eq!(memory.fetched, [0xfff, 0x1000, 0x1001]);
        for bytes in [
            &[0x0f, 0x22, 0xc1][..],
            &[0x0f, 0x22, 0xc6][..],
            &[0x0f, 0x22, 0xc2][..],
            &[0x48, 0x0f, 0x22, 0xc7][..],
            &[0x40, 0x0f, 0x22, 0xc7][..],
            &[0x41, 0x0f, 0x22, 0xc7][..],
            &[0x44, 0x0f, 0x22, 0xc7][..],
            &[0x66, 0x0f, 0x22, 0xc7][..],
            &[0x67, 0x0f, 0x22, 0xc7][..],
            &[0xf3, 0x0f, 0x22, 0xc7][..],
            &[0x2e, 0x0f, 0x22, 0xc7][..],
            &[0xf0, 0x0f, 0x22, 0xc7][..],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        // The existing RAX form is unchanged.
        assert_eq!(
            Memory::new(&[0x0f, 0x22, 0xc0]).decode().unwrap().operation,
            Operation::WriteCr0
        );
    }

    #[test]
    fn cr0_moves_and_lock_ud_have_exact_register_forms_and_full_fetch() {
        for (bytes, operation) in [
            (&[0x0f, 0x20, 0xc0][..], Operation::ReadCr0),
            (&[0x0f, 0x22, 0xc0][..], Operation::WriteCr0),
            (&[0x0f, 0x22, 0xd8][..], Operation::WriteCr3),
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.operation, operation);
            assert_eq!(instruction.length, 3);
            assert_eq!(instruction.prefixes, Prefixes::default());
            assert_eq!(memory.fetched, [0xfff, 0x1000, 0x1001]);
        }

        for bytes in [&[0xf0, 0x0f, 0x20, 0xc0][..], &[0xf0, 0xdb, 0xe3][..]] {
            let mut memory = Memory::new(bytes);
            assert!(matches!(memory.decode(), Err(DecodeError::Invalid { .. })));
            assert_eq!(memory.fetched.len(), bytes.len());
        }

        let mut memory = Memory::new(&[0xf0, 0x0f, 0x22, 0xc0]);
        assert!(matches!(
            memory.decode(),
            Err(DecodeError::InvalidMovCr0Lock { .. })
        ));
        assert_eq!(memory.fetched, [0xfff, 0x1000, 0x1001, 0x1002]);
        let mut memory = Memory::new(&[0xf0, 0xf0, 0x0f, 0x22, 0xc0]);
        assert!(matches!(
            memory.decode(),
            Err(DecodeError::Unsupported { .. })
        ));
        let mut memory = Memory::new(&[0x40, 0xf0, 0x0f, 0x22, 0xc0]);
        assert!(matches!(memory.decode(), Err(DecodeError::Invalid { .. })));
        assert_eq!(memory.fetched.len(), 5);

        for (bytes, length) in [
            (&[0x0f, 0x20, 0xd8][..], 3),
            (&[0x48, 0x0f, 0x20, 0xd8][..], 4),
        ] {
            let mut memory = Memory::new(bytes);
            let instruction = memory.decode().unwrap();
            assert_eq!(instruction.operation, Operation::ReadCr3);
            assert_eq!(instruction.length, length);
        }
        for bytes in [
            &[0x66, 0x0f, 0x20, 0xd8][..],
            &[0xf0, 0x0f, 0x20, 0xd8][..],
            &[0xf3, 0x0f, 0x20, 0xd8][..],
            &[0x67, 0x0f, 0x20, 0xd8][..],
            &[0x2e, 0x0f, 0x20, 0xd8][..],
            &[0x4c, 0x0f, 0x20, 0xd8][..],
            &[0x0f, 0x20, 0x18][..],
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
        assert!(matches!(
            Memory::new(&[0xf0, 0x0f, 0x22, 0xd8]).decode(),
            Err(DecodeError::InvalidMovCr3Lock { .. })
        ));

        for bytes in [&[0x0f, 0x20, 0xc1][..], &[0x0f, 0x22, 0xc1][..]] {
            let mut memory = Memory::new(bytes);
            assert!(matches!(
                memory.decode(),
                Err(DecodeError::Unsupported { .. })
            ));
            assert_eq!(memory.fetched.len(), bytes.len());
        }
        for bytes in [&[0x48, 0x0f, 0x20, 0xc0][..], &[0x66, 0x0f, 0x22, 0xc0][..]] {
            assert!(matches!(
                Memory::new(bytes).decode(),
                Err(DecodeError::Unsupported { .. })
            ));
        }

        for bytes in [
            &[0x0f][..],
            &[0x0f, 0x20][..],
            &[0xf0, 0x0f, 0x22][..],
            &[0xf0, 0xdb][..],
        ] {
            let mut memory = Memory::new(bytes);
            assert!(memory.decode().is_err());
            assert_eq!(memory.fetched.len(), bytes.len() + 1);
        }
    }

