    #[test]
    fn cvtpd2dq_decodes_all_canonical_register_pairs_and_rejects_neighbors() {
        for destination in 0u8..16 {
            for source in 0u8..16 {
                let modrm = 0xc0 | ((destination & 7) << 3) | (source & 7);
                let mut bytes = vec![0xf2];
                if destination >= 8 || source >= 8 {
                    bytes.push(0x40 | ((destination >> 1) & 4) | (source >> 3));
                }
                bytes.extend_from_slice(&[0x0f, 0xe6, modrm]);
                let instruction = Memory::new(&bytes).decode().unwrap();
                assert_eq!(instruction.length as usize, bytes.len());
                assert_eq!(
                    instruction.operation,
                    Operation::Cvtpd2dqRegister {
                        destination,
                        source
                    },
                    "{bytes:02x?}"
                );
            }
        }

        assert!(matches!(
            Memory::new(&[0xf3, 0x0f, 0xe6, 0xc1])
                .decode()
                .unwrap()
                .operation,
            Operation::Cvtdq2pdRegister { .. }
        )); // The adjacent F3 form keeps its independent CVTDQ2PD admission.

        assert_eq!(
            Memory::new(&[0xf2, 0x0f, 0xe6, 0x00])
                .decode()
                .unwrap()
                .operation,
            Operation::Cvtpd2dqMemoryRax
        );

        for bytes in [
            &[0xf2, 0x0f, 0xe6, 0x08][..],             // other memory operand
            &[0xf2, 0x48, 0x0f, 0xe6, 0xc1][..],       // REX.W
            &[0xf2, 0x42, 0x0f, 0xe6, 0xc1][..],       // REX.X
            &[0xf2, 0x40, 0x0f, 0xe6, 0xc1][..],       // unnecessary REX
            &[0xf2, 0xf2, 0x0f, 0xe6, 0xc1][..],       // repeated mandatory prefix
            &[0x41, 0xf2, 0x0f, 0xe6, 0xc1][..],       // reordered REX
            &[0x66, 0xf2, 0x0f, 0xe6, 0xc1][..],       // additional prefix
            &[0xc5, 0xf9, 0xe6, 0xc1][..],             // VEX
            &[0x62, 0xf1, 0x7d, 0x08, 0xe6, 0xc1][..], // EVEX
        ] {
            assert!(
                matches!(
                    Memory::new(bytes).decode(),
                    Err(DecodeError::Unsupported { .. })
                ),
                "{bytes:02x?}"
            );
        }
    }

